var SURGERY_STORE = {
	bookings: [],
	roles: [],
	listeners: /* @__PURE__ */ new Set(),
	_timers: [],
	createBooking(input, roleKeys) {
		const id = "sb-" + Math.random().toString(36).slice(2, 9);
		const roleFees = input.role_fees || {};
		this.bookings = [{
			id,
			facility_id: "hub-demo",
			status: "broadcasting",
			created_at: Date.now(),
			...input
		}, ...this.bookings];
		roleKeys.forEach((rk) => {
			this.roles = [...this.roles, {
				id: "sr-" + Math.random().toString(36).slice(2, 9),
				booking_id: id,
				role: rk,
				assigned_to: null,
				provider_name: null,
				eta_min: null,
				fee: roleFees[rk] ?? (SURGERY_ROLES[rk]?.fee || 0),
				status: "pending",
				accepted_at: null
			}];
		});
		this._emit();
		return id;
	},
	acceptRole(roleId, providerName) {
		this.roles = this.roles.map((r) => r.id === roleId && r.status === "pending" ? {
			...r,
			status: "accepted",
			provider_name: providerName,
			assigned_to: "me",
			eta_min: r.eta_min ?? 20,
			accepted_at: Date.now()
		} : r);
		this._checkComplete();
		this._emit();
	},
	cancelBooking(id) {
		this.bookings = this.bookings.map((b) => b.id === id ? {
			...b,
			status: "cancelled"
		} : b);
		this.roles = this.roles.map((r) => r.booking_id === id && r.status === "pending" ? {
			...r,
			status: "declined"
		} : r);
		this._emit();
	},
	simulate(bookingId) {
		this.roles.filter((r) => r.booking_id === bookingId && r.status === "pending").forEach((r, i) => {
			const t = setTimeout(() => {
				const pool = SURGERY_PROVIDER_POOL[r.role] || [{
					name: "Dr. On-call",
					eta: 25
				}];
				const p = pool[Math.floor(Math.random() * pool.length)];
				this.roles = this.roles.map((x) => x.id === r.id && x.status === "pending" ? {
					...x,
					status: "accepted",
					provider_name: p.name,
					eta_min: p.eta,
					accepted_at: Date.now()
				} : x);
				this._checkComplete();
				this._emit();
			}, 1800 + i * 2100);
			this._timers.push(t);
		});
	},
	_checkComplete() {
		this.bookings = this.bookings.map((b) => {
			if (b.status !== "broadcasting") return b;
			const rs = this.roles.filter((r) => r.booking_id === b.id);
			return rs.length && rs.every((r) => r.status === "accepted") ? {
				...b,
				status: "confirmed"
			} : b;
		});
	},
	_emit() {
		this.listeners.forEach((fn) => {
			try {
				fn();
			} catch (e) {}
		});
	},
	subscribe(fn) {
		this.listeners.add(fn);
		return () => this.listeners.delete(fn);
	}
};
function useSurgeryStore() {
	const [, force] = React.useState(0);
	React.useEffect(() => SURGERY_STORE.subscribe(() => force((n) => n + 1)), []);
	return SURGERY_STORE;
}
