function providerOptionsForService(svc) {
	const tab = svc?.tab;
	try {
		if (tab === "doctor") return (typeof DOCTORS_EXT !== "undefined" ? DOCTORS_EXT : []).map((d) => ({
			id: d.id,
			name: d.name.split(" / ")[0],
			sub: d.shortName,
			avail: d.avail
		}));
		if (tab === "therapist") return (typeof THERAPISTS !== "undefined" ? THERAPISTS : []).map((x) => ({
			id: x.id,
			name: x.name,
			sub: x.desc,
			avail: x.avail
		}));
		if (tab === "technician") return (typeof TECHNICIANS !== "undefined" ? TECHNICIANS : []).map((x) => ({
			id: x.id,
			name: x.name,
			sub: x.desc,
			avail: x.avail
		}));
		if (tab === "scan") return (typeof SCANS !== "undefined" ? SCANS : []).map((x) => ({
			id: x.id,
			name: x.name,
			sub: x.desc,
			avail: x.avail
		}));
		if (tab === "hospital") return (typeof HOSPITALS !== "undefined" ? HOSPITALS : []).map((h) => ({
			id: h.id,
			name: h.name,
			sub: h.area,
			avail: h.beds
		}));
	} catch (_) {}
	return [];
}
function alternatesForService(svc, chosenId) {
	return providerOptionsForService(svc).filter((o) => o.id !== chosenId).sort((a, b) => (b.avail || 0) - (a.avail || 0)).slice(0, 3).map((o) => ({
		id: o.id,
		name: o.name,
		avail: o.avail || 0
	}));
}
